INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','آموزش کامل و عملی برای کشاورزان عراقی درباره محاسبه هزینه کشت ذرت با نوار تیپ در هکتار، از خرید بذر و تجهیزات تا نگهداری و برداشت، همراه با نکات اقتصادی و فنی. محتوای این راهنما به کمک داده‌های دقیق و تجارب عملی، کمک می‌کند تا بهترین تصمیمات را برای افزایش بهره‌وری و سودآوری مزرعه خود بگیرید.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
