INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','Дар ин мақола арзиши ғарси задуни картошка бо усули лентаи тиб дар ҳекторро баррасӣ мекунем. Раҳнамои амалӣ ва иқтисодии комил барои деҳқонҳои тоҷик, ки мехоҳанд самаранокии хурдуниро зиёд кунанд.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
