INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаддима: Чаро системаи оварӣ-қатрабарӣ барои хуругӣ мувофиқ аст?</h2>\n<p>Хуругӣ яке аз растаниҳои бозоргонӣ аст, ки ба об, намӣ ва ғизо хеле ҳассос аст. Ин растанӣ сабаби сохтори решаҳои пастеи ӯ, ки бо оварӣ-қатрабарӣ оварда мешавад, ва истеъмолнокии баланди об дар марҳилаҳои афзоиш ва мевадиҳӣ, ба муҳитҳои бо намии якхела таваҷҷӯҳи ҳатмӣ дорад. Истифодаи <strong>нӯҳӣ-оаварӣ-қатрабарӣ</strong> сабаби имконияти идоракунии дақиқи намии реша, камакнии бухор ва шӯротобии самаранок, беҳтарин усул барои парвариши ин маҳсулот мебошад. Дар ин мақола, мо як дастрасоии қадам-ба-қадам ва комил барои ғаланди хуругӣ бо оварӣ-қатрабарӣ пешниҳод мекунем, ки аз марҳилаҳои ибтидоии тайёрсозии замин ва ғаланди дунб, то нақшаёрии дақиқи оварӣ ва идоракунии ғизо дар марҳилаҳои гуногуни афзоишро бо тамоми ҷиҳатҳо дар бар мегирад.</p>\n<p>Интихоби дурусти нӯҳӣ-оаварӣ аз ҷиҳати масофаи қатрабарӣ, анҷомгурии ҷарӣ ва қутри лӯла, бевосита ба сифати якхелӣ-мева ва ҳаҷми истеҳсол дар ҳеҷар зиёда таъсир мерасонад. Ноомонӣ дар ин параметрҳо метавонад ба афзоиши ноумеди растаниҳо ва камшавии samaradории боғдонӣ оварда расонад. Барои шиносӣ бо асосҳои техникии интихоби лӯлакашӣ, омӯзиши мавзӯи <a href="https://navar-abyari.ir/ahamiyati-bozinsii-zamin-baroi-navori-tip-va-nayii-poli/" target="_blank" rel="noopener">аҳамияти вазни замин барои нӯҳӣ-оаварӣ ва лӯлаи полиетилени</a> меёнад назари дақиқтарро дар бораи интихобҳои техники ва бехатарии сохторӣ ба шумо диҳад. Инчунин дарки он, ки пайвастҳо чӣ гуна амал мекунанд ва интихоби фитинги мувофиқ, аз ҷумла баррасии имкониятҳои <a href="https://navar-abyari.ir/lula-3-dyimmagi-kharid-istifoda-imkoniyathoi/" target="_blank" rel="noopener">харид ва истифода аз лӯлаи се-роҳа</a>Барои таъмини фишори якхела ва бидуни камшавӣ дар давоми ҳар як давра (Run) дар боғҳои бузург муҳим аст. Ин пайвастҳо бояд мувофиқ ба фишори кории системаи фишор додан интихоб шаванд, то аз намуни микро пешгирӣ карда шавад.</p>\n\n<h2>Омодагии замин ва кӯришанбазар</h2>\n<h3>Омодагии хок ва ламбобирии аввал</h3>\n<p>Пеш аз кӯришанбазар, таҳлили хок аз ҷиҳати pH (минаи мувофиқ 6.0 то 7.5) ва EC (камтар аз 1.5 ds/m барои хокҳои солонак бо хосияти шурӣ) зарурӣ аст. Хокҳои сабуку миёна бо обниши хуб барои кӯришан бештар мувофиқанд, зеро решаҳои кӯришан ба ҳавои зери реша ҳассос аст. Пас аз кашидани рӯдҳои асосӣ ва мусовар кардани замин, ламбиҳои дақакиро дар масофаи 40 то 50 сантиметрӣ аз ҷойи кӯришан ҳар сатр (дар системаи сатрии ягона) ё байни сатрҳо (дар системаи сатрии дутоӣ) насб кунед. Риояи дақиқи чуқургии кӯришан (одатан 1 то 2 сантиметр) ва масофаҳои стандартии ба кафолати рушди якхелаи анӯрон ва ҷабҷабҳои оптималӣ барои реша ба минтақаи намноки ламби таъмин карда мешавад.</p>\n<ul>\n<li>Навъи кӯришан: сатрӣ ё кӯҳикӣ (кӯҳикӣ барои обниши хубтар тавсия карда мешавад)</li>\n<li>Масофаи байни сатрҳо: ҳадди ақал 90 то 100 сантиметр (вобаста ба системаи хонаи шамъёр ё корбашкард)</li>\n<li>Масофаи бозиҳо дар сатр: 20 то 25 сантиметр (барои коҳиши чизшавӣ дар хонаҳои шамъёри зиёд)</li>\n<li>Чуқурии кӯришан: 1 то 2 сантиметр дар байни ламбиҳои обдорӣ</li>\n</ul>\n<p>Барои вонҳое, ки чандмҳосиларо реҷа мекунад ва дар қиблат мутаносибатҳои ғалзати партод ва талаботҳои сатҳи замин мебинанд, ошкор будани зарибҳои истифодаи маҳсулоти дигар, ба монанди санҷиш <a href="https://navar-abyari.ir/%d9%85%d9%82%d8%af%d8%a7%d8%b1-%d8%a8%d8%b0%d8%b1-%d8%b0%d8%b1%d8%aa-%d8%b9%d9%84%d9%88%d9%81%d9%87-%d8%a7%db%8c-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/" target="_blank" rel="noopener">андозаи бехи гулкаши ошнокро дар ҳектар</a> меёвад метавонад миқёси ишорагир барои ҳисобҳои масоҳат ва чапаи партод бо партодишӣ бошад. Агар баъзан, гулкаши ошнок сабаб ба афзоиши тез, устуворӣ ва шикастани зиёд, ба ҳайси ғалзат ва идоракунии фазои сабз ҷудогонаи лозим дорад, ки бояд дар тарҳрезии аввалини системаи обёркунӣ ба назар гирифта шавад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-خیار-با-آبیاری-قطرهای-تصویر-شاخص.webp" alt="راهنمای جامع کاشت خیار با آبیاری قطره‌ای - تصویر 1"/><figcaption>усулҳои партод, маҳсулоти ошнок, реҷаи обёркунии қатъоии гулкаши ошнок</figcaption></figure>\n\n\n<h3>Интихоби системаи мувофиқи обёркунӣ ва нуби қатъоӣ</h3>\n<p>Барои гулкаши ошнок, ки афзоиши тез ва истифодаи баланди об дорад, истифодаи нубаҳо бо фосилаи қатъо 10 ё 15 сантиметр тавсия мешавад. Интихоби фосилаи қатъо ба чуқурии бахшидани решаи асосӣ муҳим аст; решаи гулкаши ошнок асосан дар 30 то 45 сантиметри буриши хок ҷойгир мешавад. Агар шумо дар ҷустуҷӯи беҳтар кардани интихоби худ бошед, роҳнамои чӣ тавр нуби мувофиқи обёркунии қатъоӣ интихоб карданро бо диққат санҷед, то аз халӣ на будани система кафолат карда шавад ва саросири бори ҳар як қатҳо бо шароитҳои иқлимии минтақаи шумо мувофиқат бошад. Дар минтақаҳои хушк ва бо бухори баланд, нубаҳо бо фосилаи камтар ва саросири бори зиёдтар барои нигоҳ доштани намӣ дар минтақаи решаҳо зарур аст. Инчунин намуди девори нуб (дурахшон ё ғайридурахшон) бояд асосан ба эҳтимоли вайрон кардан тавассути мошинҳои партод ва таҳия интихоб шавад.</p>\n\n<h2>Реҷасозии обёркунӣ ва ғизои гулкаши ошнок дар марҳилаҳои гуногуни афзоиш</h2>\n<p>Мудирияти намнокӣ дар хурмо муҳим аст. Камӣ ноқисии об боиси лағзидани мева, қатъи рӯшӣ ва партоби гулҳо мегардад, дар ҳоле ки обдории зиёд боиси бемориҳои реша ва чаконидашудан мешавад. Мувозинат байни об ва оксиген дар реша калиди саломатии расток аст. Дар поён, барномасозии обдорӣ бо вобастагӣ ба синну соли расток ва ниёзҳои физиологӣ оварда шудааст. Бояд дар назар дошт, ки обдории кӯтоҳ ва такрорӣ беҳтар аз обдории тӯл ва камшумора аст.</p>\n<table border="1" cellpadding="8" cellspacing="0" style="border-collapse: collapse; width: 100%;">\n<thead>\n<tr><th style="background-color:#f2f2f2;">Марҳилаи афзоиши хурмо</th><th style="background-color:#f2f2f2;">Шумораи маротибаҳои обдорӣ дар рӯз</th><th style="background-color:#f2f2f2;">Моддати тақрибии об (литр/маротиба/қатра)</th><th style="background-color:#f2f2f2;">Нуқтаҳои ғизоӣ ва оҳудӣ</th></tr>\n</thead>\n<tbody>\n<tr><td>Дадон ва рӯшӣ (0-4 ҳафта)</td><td>1 то 2</td><td>50-100</td><td>Истифодаи моддаҳои азотнок камгузав ва тавр таъминӣ</td></tr>\n<tr><td>Ҳабб ва гулдоҳӣ (5-10 ҳафта)</td><td>2 то 3</td><td>150-250</td><td>Баланд бурдани калий ва кальсий барои сифати мева</td></tr>\n<tr><td>Давраи пас аз гулдоҳӣ ва бурдан (пас аз 10 ҳафта)</td><td>2 то 4</td><td>300-500</td><td>Мувозинати ғизоӣ ва пешгирии пӯсидагии анҷоми мева</td></tr>\n</tbody>\n</table>\n<p>Илова кардани кӯдаки фурӯпашӣ тавассути системаи оборӣ пуркашӣ (Fertigation) самаранамуди ҷазби моддаҳои ғизоиро ба таври бисёр баланд мебаданд ва аз беҳуда шудани кӯда дар сathi хак пешгирӣ мекунад. Барои фаҳмиши беҳтари принсипҳои умумии ғизои дарункишӣ ва ҳисобҳои дозҳои истифода, шумо метавонед ба манбаъҳои референтӣ чун <a href="https://navar-abyari.ir/%D9%85%DB%8C%D8%B2%D8%A7%D9%86-%D8%A8%D8%B1%D8%AF%D8%A7%D8%B4%D8%AA-%D8%AC%D8%B9%D9%81%D8%B1%DB%8C-%D8%AF%D8%B1-%D9%87%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/" target="_blank" rel="noopener">Милди ҷайҳи маҳсулоти ҳар гектар</a> ё принсипҳои умумии <a href="https://navar-abyari.ir/%D8%AA%D9%86%D8%A7%DA%98-%D9%81%D9%84%D9%81%D9%84-%D8%AF%D9%84%D9%85%D9%87-%D8%AF%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/" target="_blank" rel="noopener">тартиб додани мавсими дар ҳар гектар</a> маслиҳат кунед, ки ба дозҳои ғизоӣ ва ҷойгиркунии фазоии раҳо ойдорад. Дар системаи хурхур, барномаи ғизоӣ бояд бо зиёд шудани ҳаҷми истеҳсоли мева, аз нитрогенмарказӣ ба калиймарказӣ тағйир ёфта, то қанд ва устувии мева нигоҳ дошта шавад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-خیار-با-آبیاری-قطرهای-کاربرد-عملی.webp" alt="راهنمای جامع کاشت خیار با آبیاری قطره‌ای - تصویر 2"/><figcaption>усулҳои ҷойниши, обори пуркашӣ, нақшаи ғизои зироат, хурхур</figcaption></figure>\n\n\n<h2>Нуқтаҳои амалӣ муҳим дар идоракунии замин ва системаи техникӣ хурхур</h2>\n<ol>\n<li><strong>Назории фишори система:</strong> Ҳар рӯз ё ҳадякам ду маротиба дар як рӯз, фишори ларисаҳои обварӣро дар оғози хат (нуқтаи нам) ва дар ниҳоати хат (нуқтаи хушк) санҷед. Паст шудани фишор нишондиҳандаи хаста будани фильтр, боз шудани лӯла ё гирҳ задани қатрагирон мебошад. Барқарор будани фишор омил асосии баробарии фаъолият ва якхелагии намӣ дар тамоми майдони ғалла аст.</li>\n<li><strong>Шустани филтрҳо:</strong> Бо сабаби ҳассосияти хӯрокӣ ба намакҳо ва зарраҳои муаллақ, филтрҳо бояд ҳафтаӣ ва пеш аз ҳар истифода шуста шаванд. Истифодаи филтрҳои турбинӣ ё дискавӣ вобаста ба намуди манбаи об (қудӯқ бо зарраҳои лой зиёд ё дарё бо оғоз) шарт аст, то давomi кардани истифодаи ларисаҳои қатрагирон нигоҳ дошта шавад.</li>\n<li><strong>Танзими ҳарорати хок:</strong> Ришаи хӯрокӣ бояд дар ҳарорати 18 то 25 дараҷаи Селсий боқӣ монад. Истифодаи плёнкаи сиёҳ ё ҷӯ барои нигоҳ доштани ҳарорати мувофиқ, кам кардани отҳои зараровар ва нигоҳ доштани намии сатҳӣ тавсия мешавад. Плёнка кашидан пеш аз кишвари ғалла мувофиқтарин аст.</li>\n<li><strong>Идоракунии намии нисбӣ ва ҳарорат:</strong> Дар ҳавзаварӣ, намӣ аз 90% зиёд боиси пайдои бемориҳои қарозӣ чун сӯзонидан ва гурӯҳи нӯки мева мешавад. Обварӣ бояд дар соатҳои камнамии рӯз (нисфазамон) сурат гирад, то намии сатҳӣ бе афзудани намии ҳавои атроф пешгирӣ шавад. Ин кор ба танзими микроклимаи ҳавзаварӣ кӯмак мекунад.</li>\n</ol>\n<p>Бигиред дар назар, ки уқури хояргӣ одатан ба зичии мувофиқ ва кӯронати мустақим ниёз дорад. Бо барномароии дақиқ ва истифодаи уқурҳои стандартии генетикӣ, метавон аз зарари уқур ба сабаби намнокории бешунон оғозӣ ва бемориҳои кӯронат пешгирӣ кард. Табобати ҳаётии рӯяндии ҷудокор тавассути обнокории тамғаи қатрагӣ стресси физиологии гиёҳро ба ҳадди ақал мерасонад.</p>\n\n<h2>Саволҳои маъмул (FAQ) дар бораи кӯронати хояргӣ бо обнокории тамғаи қатрагӣ</h2>\n<h3>Фосилаи байни қатрагӣҳо дар хояргӣ чӣ қадар бояд бошад?</h3>\n<p>Барои хояргӣ, фосилаи 10 то 15 см беҳтарин имконият аст, то минтақаи решаҳои асосӣ, ки nisbatан сатҳӣ мебошад, бо шакли якхела обнокӣ шавад. Ин фосила ба чуқурӣи даромади решаҳои дуюмдараҷаи хояргӣ мувофиқат дорад ва боиси он мешавад, ки намнокӣ бо шакли миёна дар ҷои асосии ҷалби реша таъмин гардад. Дар системаҳои якҷониба, шарорӣ бояд дақиқан дар тарафи рӯшноӣ ҷойгир шавад.</p>\n\n<h3>Оё ман метавонам системаи обнокории тамғаи қатрагиро дар кӯронати хояргӣ (Field) истифода барам?</h3>\n<p>Бале, обнокории тамғаи қатрагӣ дар кӯронати хояргӣ пурра имконпазир аст ва боиси сарфакунии 30 то 50 фоизии об нисбат ба обнокории қатрагӣ ё боронӣ мегардад, аммо ба бастабандии стандартӣ, баробар будани замин ва фишори мувофиқ ниёз дорад. Дар ин ҳолат, истифодаи шинури тобнок (Reinforced) муҳимияти дучанд зиёдтар мегирад, то аз шикастани лӯла тавассути мошинҳои ҷамъоварӣ ва коркарди замин пешгирӣ шавад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-خیار-با-آبیاری-قطرهای-جزئیات-فنی.webp" alt="راهنمای جامع کاشت خیار با آبیاری قطره‌ای - تصویر 3"/><figcaption>planting methods drip crop irrigation schedule хояргӣ</figcaption></figure>\n\n\n<h3>Агар шинури tip нарханди баланд дошта бошад, чӣ ивазкунанда вуҷуд дорад?</h3>\n<p>Метавон аз системаҳои лӯлавии поли бо қатронакҳои паҳлӯ истифода баранд, аммо рибаи дробӣ барои давраҳои дарозтари истеҳсоли хӯрмо (6 моҳ ва зиёдтар) баромади сармаёфии беҳтар дорад. Лӯлаҳои полиетилен метавонанд ҳамчун инфрасохтори асосӣ ва рибаҳои дробӣ ҳамчун шохаҳои паҳлӯи он истифода шаванд. Дар ҳолатҳои маҳдудияти буҷ, истифодаи қатраҳои хатфуззӣ метавонад хароҷотҳоро коҳиш диҳад.</p>\n\n<h3>Муҳимтарин аломатҳои камбудии об дар хӯрмо чист?</h3>\n<p>Дароз шудани қалмоҳо, хурд шудани мева, тухм шудани бӯъ ва дараҷаҳои зард бар баргҳои поёнӣ аввалин аломатҳоянд. Ҳолатҳои камбудии об одатан дар соатҳои пашин, вақте ки таёриш (транспирация) ҷисм ба қуллаш мерасад, анҷумонтар мебошанд. Инчунин, пӯсиши поёни мева (Blossom End Rot) аксар вақт ба камбудии калсий оқибати стресс обии шадид ё тағйирёбии наммогиӣ вобаста аст.</p>\n\n<h2>Хулоса ва тавсияи охирин</h2>\n<p>Наткани хӯрмо бо ободории қатрагӣ як сармогузории хобарона дар кишоварзии муосир ва устувор аст. Бо риояи асосҳои интихоби рибаи мувофиқ, дақиқкунии вақти ободорӣ ва ғизои мувозанатнок, метавонед ба самаранокии баланд ва меваи якнавохт ва бо сифати экспортӣ даст ёбед. Фаромӯш накунед, ки пайгирӣи давомии солимӣи системаи лӯлавӣ ва фильтратсия кафолаткунандаи умри дарози асбобҳои шумо ва коҳиши хароҷоти таъмиркунӣ аст.combinationи дониши фанни ободорӣ бо идоракунии дурусти барг, хок ва ҷисм, калиди ғалаба дар рақобати бозори хӯрмои дохилӣ ва хориҷӣ аст. Иҷрои дақиқи ин барнома ба коҳиши истеъмолоти об, коҳиши истеъмолоти моад ва афзоиши соҳибноқии иқтисодии боғ мусоидат мекунад.</p>','Камиллаги ҳарити шӯрбо бо обори куятрагӣ: аз бомто то ҷамъоварӣ','Хариди бӯди хия, омода намудани замин ва интихоби системаи мувофиқи орлодиҳии нави тирӣ барои зиёд намудани самаранокии кишоварзӣ ва кам кардани стресси обии ҷиби хия.','publish','closed','closed','khamillagi-shurbo-obori-kuyatragi',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
